var n={_about:"Niggles (niggles-spec, Kevin 5 and 6 Nov 2026). en-IE, plain words, no em dashes. Health data: its own consent; the linked coach sees niggles only while it stands; the AI only with the player's own switch (0092, Kevin 8 Nov 2026).",title:"Niggles",consent:{title:"Before you flag a niggle",againTitle:"Before the AI uses your niggles",againBody:"We've changed what you agreed to: it now says the AI assistant can use your niggles if you switch it on. Agree to the new wording to switch it on.",kept:"We keep where it hurts, the side, how bad (0 to 10), when it started, what makes it worse, and your updates.",who:"Your linked coach sees them; nobody else, and the AI assistant only if you switch on Let the AI use my niggles in Settings.",howLong:"Kept until you clear or delete them; cleared ones are kept 12 months, then deleted.",delete:"You can delete one, all of them, or withdraw this consent in Settings, which deletes everything at once.",adult:"I'm 18 or over",tick:"I agree to The Padel Doc keeping this to help plan my training and my tournaments.",agree:"Agree and continue",cancel:"Not now"},card:{flag:"Flag a niggle",none:"No niggles. Flag one when something hurts.",since:"since {date}",pain:"{n} out of 10",updated:"Updated {date}",trend:{better:"Better",same:"Same",worse:"Worse"},howNow:"How is it now?",gone:"It's gone",edit:"Edit",editDetails:"Edit details",delete:"Delete",deleteSure:"Delete this niggle and its updates? This can't be undone.",deleteYes:"Delete",cancel:"Cancel",resolvedTitle:"Cleared in the last 12 months",resolvedOn:"cleared {date}",history:"History",max:"That's 10 niggles: clear one before flagging another.",worse:"Worse with: {list}"},log:{title:"Flag a niggle",editTitle:"Edit niggle",figure:"Which figure?",figureHint:"Pick the one that suits you. It's remembered on this device, and you can switch it on the map.",male:"Male figure",female:"Female figure",front:"Front",back:"Back",tapHint:"Tap where it hurts.",listTitle:"Or pick from the list",notOnList:"Not on the list: pick the nearest below.",picked:"{where}",side:"Which side?",pain:"How bad is it?",painHint:"0 is nothing, 10 is the worst",started:"When did it start? (optional)",worse:"What makes it worse? (optional, up to 6)",save:"Save",saveAnother:"Save and add another",savedNext:"Saved: {where}. Add the next one.",alreadyLogged:"Already logged",update:"Update",hereAlready:"{where} is already logged.",dotLabel:"{where}, {n} out of 10. Update it",cancel:"Cancel",next:"Next",change:"Change",pickWhere:"Pick where it hurts",pickPain:"Pick how bad it is",mapLoading:"Loading the body map\u2026",mapFailed:"The body map didn't load. Pick where it hurts from the list below."},worse:[{code:"running",label:"Running"},{code:"jumping",label:"Jumping"},{code:"jumping_landing",label:"Jumping and landing"},{code:"changing_direction",label:"Changing direction"},{code:"overheads",label:"Overheads"},{code:"backhand",label:"Backhand"},{code:"forehand",label:"Forehand"},{code:"volleys",label:"Volleys"},{code:"low_balls",label:"Low balls and lunging"},{code:"twisting",label:"Twisting"},{code:"gripping",label:"Gripping the racket"},{code:"serving",label:"Serving"},{code:"mornings",label:"Mornings"},{code:"after_playing",label:"After playing"}],painLines:[{from:4,to:5,text:"Tell your coach or the on-site physio before the next match."},{from:6,to:10,text:"Get this checked before you play on."}],settings:{title:"Who sees your niggles",consented:"You agreed on {date}.",notConsented:"You haven't flagged a niggle yet.",deleteAll:"Delete my niggles",deleteAllSure:"Delete every niggle and its history? Your consent stays.",withdraw:"Withdraw consent",withdrawSure:"Withdraw consent and delete everything: every niggle, its history, and any pain from your tournament check-ins?",withdrawn:"Done. Everything's deleted.",aiLabel:"Plan my gym sessions around my niggles",aiHint:"The AI builds each session around what's sore, so you can keep training. Off unless you switch it on.",aiMore:"Where it is, how bad (out of 10) and what makes it worse are sent, never any notes. A niggle at 6 or more isn't sent: exercises that load that area are left out and your plan tells you to see a physio.",yes:"Yes, delete",cancel:"Cancel"},coach:{title:"Niggles",none:"{name} hasn't flagged any niggles.",notShared:"No niggles shared.",line:"{where}, {n} out of 10",avoid:"{name} rates this {n} out of 10. Think about Avoid impact, or swapping the exercises that load it.",history:"History",resolved:"Cleared",readOnly:"Only {name} can change these."},fieldErrors:{required:"Add this",date:"A date in the last year, not in the future"},error:"Something went wrong. Try again."};export{n as a};
